solution:
def can_open_all(keys: list[list[int]]) -> bool:
    opened, stack = {0}, [0]
    while stack:
        for room in keys[stack.pop()]:
            if room not in opened:
                opened.add(room)                 # mark on push: each room is entered once
                stack.append(room)
    return len(opened) == len(keys)

