perf.naive:
def can_open_all(keys: list[list[int]]) -> bool:
    opened, changed = {0}, True
    while changed:                           # sweep the rooms in order until a pass opens nothing
        changed = False
        for room in range(len(keys)):
            if room in opened:
                for key in keys[room]:
                    if key not in opened:
                        opened.add(key)
                        changed = True
    return len(opened) == len(keys)
